\label{thm:main}
Every convex body $K\subset\mathbb R^3$ of constant width $w>0$ satisfies
\begin{equation}\label{eq:main}
 \boxed{\operatorname{Vol}(K)\ge\frac{1651}{4000}w^3=0.41275\,w^3.}
\end{equation}

\label{lem:sharpD}
For four points on a common sphere, with $0\le\delta_{ij}$ and $D<1$,
\[
 |b|^2\le\frac{D^2}{16(2+D)}.
\]
For a balanced contact tetrahedron with $R\ge0.6$, this gives
\begin{equation}\label{eq:sharpD}
 \boxed{D\le\frac{16d}{1-8d}.}
\end{equation}
Equality in the first inequality is attained on the one-shortened-edge vertices of the deficit simplex.

\label{lem:faceinclusion}
The following entire region lies in $K$:
\begin{equation}\label{eq:newface}
 \left\{p+tn:p\in F,\quad
 0\le t\le\sqrt{\kappa^2+W(p)}-\kappa\right\}.
\end{equation}
